Section EXITS.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis SSF8 : set_shadow_stmt 0xf8 ASET_SHADOW_F8.
  Hypothesis FREE7 : stack_free_7_stmt H.
  Hypothesis MEMCPY : asan_memcpy_stmt.
  Hypothesis ASSIGNA : aassignA_stmt.

(* [comment removed for export] *)
Local Ltac exit_close_done MU1 WM1 HC4 SPI :=
  lazymatch goal with
  | SD : ipf_side _ _ ?m ?m1 ?lo _ _ _ ?P ?E _ _, MU : munch _ ?m ?m1,
    PFT : APfTab ?m1, FTS : AFieldTabZero ?m1 \/ FT ?m1, FTI : FTInit ?m1,
    CEIL : aceil <= ?lo, LO : ?lo + _ <= bv_unsigned _, GAPE : ?spa + 184 + _ = _, SPA1 : bv_unsigned _ + -304 <= ?spa, AF1 : _ <= aceil <= _,
    EB1 : 6832128 <= ?E, PB1 : 6832128 <= ?P
    |- evt _ _ (MS _ _ _ _ _ ?m4 _) =>
    let SD4 := fresh "SD4" in let PFT4 := fresh "PFT4" in let FTS4 := fresh "FTS4" in let FTI4 := fresh "FTI4" in
    assert (SD4 := ipf_side_step _ HH _ _ _ _ m4 _ _ _ _ _ _ _ _ SD MU1 WM1 ltac:(iwin_tac ltac:(clear - CEIL LO SPA1 SPI AF1; lia)));
    assert (PFT4 : APfTab m4)
      by (unfold APfTab in *; eapply (rw_cells_transport bsegs _ m1 m4); [exact PFT| exact MU1| exact WM1|];
          fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; unfold APF_TABPTR; clear - CEIL LO SPA1 AF1 EB1 SPI; lia);
    assert (FTS4 : AFieldTabZero m4 \/ FT m4)
      by (eapply FTState_transport; [exact FTS| exact MU1| exact WM1|]; cbn [disjoint_from fst snd]; unfold AG_FIELD_TABLE; clear - CEIL LO SPA1 AF1 EB1 PB1 SPI; lia);
    assert (FTI4 : FTInit m4)
      by (eapply FTInit_transport; [exact FTI| exact MU1|]; cbn [disjoint_from fst snd]; unfold P_A_FT_INIT; clear - CEIL LO SPA1 AF1 EB1 SPI; lia);
    munch_into MU MU1 ltac:(clear - LO SPA1 GAPE CEIL; lia);
    clear SD PFT FTS FTI;
    pose proof (ipf_done H HH SSF8 FREE7) as EX; unfold dof_sav, ipf_s1f, sh7, wz in EX; rewrite ?ASHADOW_BASE_val in EX;
    eapply EX; clear EX; try fast_eassumption
  end.

(* [comment removed for export] *)
Local Ltac block_cat :=
  lazymatch goal with
  | HC2 : AHttpCat ?m2 true, MU3' : munch [_; _] ?m2 ?m4, WM3' : wmono _ ?m2 ?m4, SD : ipf_side _ _ _ _ ?lo _ _ _ _ ?E _ _,
    CEIL : aceil <= ?lo, LO : ?lo + _ <= bv_unsigned _, SPA1 : bv_unsigned _ + -304 <= _, AF1 : _ <= aceil <= _, EB1 : 6832128 <= ?E
    |- evt _ _ (MS _ _ _ _ _ ?m4 _) =>
    let HC4 := fresh "HC4" in
